class MyRNNCell(nn.Module):
    def __init__(self, emb_dim, hidden_dim):
        super().__init__()
        self.W_e = nn.Linear(emb_dim,    hidden_dim, bias=False)
        self.W_h = nn.Linear(hidden_dim, hidden_dim, bias=True)

    def forward(self, e_t, h_prev):
        # the lecture equation, verbatim
        return torch.tanh(self.W_h(h_prev) + self.W_e(e_t))


cell = MyRNNCell(8, 16)
h = cell(torch.randn(4, 8), torch.zeros(4, 16))
print("h:", tuple(h.shape), "(batch 4, hidden 16)")
assert h.shape == (4, 16)
