# what does the model think comes next?  (no sampling - just the top 5 probabilities)
@torch.no_grad()
def top5(m, prompt, k=5):
    m.eval()
    h = torch.zeros(1, m.hidden_dim, device=device)
    for c in prompt:
        if c in stoi:
            h = m.cell(m.emb(torch.tensor([stoi[c]], device=device)), h)
    probs = torch.softmax(m.out(h), dim=-1)[0]
    v, idx = torch.topk(probs, k)
    m.train()
    return [(itos[int(j)], float(x)) for j, x in zip(idx, v)]


